  'bk.restored': '{n} ரெக்கார்டுகள் திரும்பக் கொண்டுவரப்பட்டன. உங்களிடம் ஏற்கெனவே இருந்த புதிய ரெக்கார்டுகள் அப்படியே வைக்கப்பட்டன.',
  'bk.nothing': 'அந்த ஃபைலில் புதிதாக எதுவும் இல்லை: அதில் உள்ள அனைத்தும் ஏற்கெனவே உங்களிடம் உள்ளன.',
  'bk.unread': 'அந்த ஃபைலைப் படிக்க முடியவில்லை.',
  'rm.ago': 'உங்கள் கடைசி பேக்கப் {n} நாட்களுக்கு முன்பு எடுக்கப்பட்டது. இந்த பிரவுசர் கிளியர் ஆனாலும் உங்கள் வேலை பாதுகாப்பாக இருக்க, ஒரு பேக்கப் ஃபைலை சேவ் செய்யவும்.',
  'rm.none': 'உங்களிடம் {n} சேவ் செய்த டாக்குமெண்டுகள் உள்ளன, ஆனால் இன்னும் பேக்கப் இல்லை. இந்த பிரவுசர் கிளியர் ஆனாலும் உங்கள் வேலை பாதுகாப்பாக இருக்க, ஒரு பேக்கப் ஃபைலை சேவ் செய்யவும்.',
