  'md.shared': 'உங்கள் டேட்டா இந்த டிவைஸின் பிரவுசரிலேயே, எல்லா Nivesh Sahayak டாக்குமெண்ட் டூல்களும் பகிர்ந்து பயன்படுத்தும் ஒரே இடத்தில் வைக்கப்படுகிறது. எங்களுக்கு எதுவும் அனுப்பப்படுவதில்லை.',
  'md.local': 'உங்கள் டேட்டா இந்த டிவைஸின் பிரவுசரிலேயே வைக்கப்படுகிறது. எங்களுக்கு எதுவும் அனுப்பப்படுவதில்லை. பகிரப்பட்ட டேட்டா இடத்தை இப்போது திறக்க முடியவில்லை, அதனால் இந்த சைட் தற்போதைக்கு அதைத் தானே வைத்திருந்து, பிறகு தானாகவே அங்கே மாற்றிவிடும்.',
