  'hub.home': 'தொடக்கம்',
  'hub.backup': 'பேக்கப் மற்றும் மற்ற டிவைஸ்கள்',
  'hub.link': 'சேவ் செய்த பிசினஸ், வாடிக்கையாளர், ஐட்டம் மற்றும் செட்டிங்',
