  'hub.s1': 'உங்கள் பிசினஸைச் சேர்க்கவும் (பெயர், GSTIN, பேங்க், லோகோ)',
  'hub.s2': 'உங்கள் வாடிக்கையாளர்கள் மற்றும் சப்ளையர்களைச் சேர்க்கவும்',
  'hub.s3': 'நீங்கள் விற்கும் ஐட்டம்கள் மற்றும் சர்வீஸ்களைச் சேர்க்கவும்',
  'hub.s4': 'இன்வாய்ஸ் நம்பரிங் மற்றும் டிஃபால்ட்டைத் தேர்ந்தெடுக்கவும்',
  'hub.s5': 'உங்கள் முதல் இன்வாய்ஸை உருவாக்குங்கள்',
  'hub.s6': 'பேக்கப் ஃபைலை சேவ் செய்யுங்கள்',
  'hub.tools': 'இந்த டேட்டாவைப் பயன்படுத்தும் டூல்கள்',
  'hub.billing': 'GST டாக்ஸ் இன்வாய்ஸ், பில் ஆஃப் சப்ளை மற்றும் சாதாரண இன்வாய்ஸ் மேக்கர்',
  'hub.toolsp': 'இங்கே சேர்ப்பது எல்லாம் இந்த பிரவுசரில் Nivesh Sahayak-இன் ஒவ்வொரு டாக்குமெண்ட் டூலிலும் பரிந்துரையாகத் தெரியும். தானாக எதுவும் நிரம்பாது: நீங்களே தேர்ந்தெடுக்கிறீர்கள்.',
  'hub.add.biz': 'பிசினஸ் சேர்க்கவும்',
  'hub.add.party': 'வாடிக்கையாளர் அல்லது சப்ளையர் சேர்க்கவும்',
  'hub.add.item': 'ஐட்டம் அல்லது சர்வீஸ் சேர்க்கவும்',
  'hub.edit.biz': 'பிசினஸை மாற்றவும்',
  'hub.edit.party': 'வாடிக்கையாளர் அல்லது சப்ளையரை மாற்றவும்',
  'hub.edit.item': 'ஐட்டம் அல்லது சர்வீஸை மாற்றவும்',
  'hub.newdoc': 'புதிய இன்வாய்ஸ் உருவாக்கவும்',
  'hub.p.biz': 'நீங்கள் டாக்குமெண்ட் உருவாக்கும் பிசினஸ்கள். அவற்றின் பெயர், முகவரி, GSTIN, பேங்க் விவரம், லோகோ மற்றும் கையெழுத்து உங்கள் டாக்குமெண்டில் அச்சாகும்.',
  'hub.p.party': 'நீங்கள் பில் போடும் அல்லது வாங்கும் நபர்கள் மற்றும் நிறுவனங்கள். எந்த டூலிலும் பெயரை டைப் செய்து தேர்ந்தெடுத்தால் முகவரி, மாநிலம், GSTIN நிரம்பும்.',
  'hub.p.item': 'பொருட்கள் மற்றும் சர்வீஸ்கள், அவற்றின் HSN/SAC கோடு, யூனிட், ரேட் மற்றும் GST உடன். எந்த டூலிலும் தேர்ந்தெடுத்தால் வரி நிரம்பும்.',
  'hub.p.doc': 'இந்த பிரவுசரில் சேவ் செய்த ஒவ்வொரு டாக்குமெண்டும். திறப்பது, காப்பி செய்வது அல்லது பெய்டு என குறிப்பது அதை உருவாக்கிய டூலிலேயே செய்யுங்கள்.',
  'hub.empty.biz': 'இன்னும் எந்த பிசினஸும் சேவ் ஆகவில்லை. தொடங்க உங்கள் பிசினஸைச் சேர்க்கவும்.',
  'hub.empty.party': 'இன்னும் வாடிக்கையாளர்களோ சப்ளையர்களோ இல்லை. ஒவ்வொன்றாகச் சேர்க்கவும் அல்லது Excel-இலிருந்து CSV ஃபைலை இம்போர்ட் செய்யவும்.',
  'hub.empty.item': 'இன்னும் ஐட்டம்களோ சர்வீஸ்களோ இல்லை. ஒவ்வொன்றாகச் சேர்க்கவும் அல்லது Excel-இலிருந்து CSV ஃபைலை இம்போர்ட் செய்யவும்.',
  'hub.empty.doc': 'இன்னும் எந்த டாக்குமெண்டும் சேவ் ஆகவில்லை.',
  'hub.imp': 'CSV இம்போர்ட்',
  'hub.exp': 'CSV எக்ஸ்போர்ட்',
