  "lg.einv": "இ-இன்வாய்ஸ் மற்றும் இ-வே பில்",
  "ei.intro": "இ-இன்வாய்ஸ் (டர்ன்ஓவர் ₹5 கோடிக்கு மேல்) அல்லது இ-வே பில் (₹50,000-க்கு மேல் மதிப்புள்ள சரக்கு அனுப்புதல்) செய்ய வேண்டிய பிசினஸ்களுக்கு. இங்கே ஃபைலை டவுன்லோட் செய்து, அரசு போர்ட்டலில் அப்லோட் செய்து, பிறகு போர்ட்டலின் பதிலை இங்கே லோட் செய்யுங்கள்: இன்வாய்ஸ் IRN மற்றும் QR கோடுடன் பிரிண்ட் ஆகும்.",
