  "ei.qr": "கையொப்பமிட்ட QR கோடு டெக்ஸ்ட்",
  "ei.h.qr": "eyJ என்று தொடங்கும் நீண்ட டெக்ஸ்ட். இது இல்லாவிட்டால் இன்வாய்ஸ் இ-இன்வாய்ஸ் QR கோடு இல்லாமல் பிரிண்ட் ஆகும்.",
  "ei.ewbno": "இ-வே பில் எண்",
