  "k.other": "மற்றவை",
  "kh.job": "வேலைக்காக ஜாப் வொர்க்கருக்கு அனுப்பும் சரக்கு. அவை திரும்பி வரும் அல்லது வேலைக்கு பிறகு பில் போடப்படும்.",
  "kh.approval": "வாடிக்கையாளர் பார்ப்பதற்காக அனுப்பும் சரக்கு. அவர் வைத்துக்கொண்டால் டாக்ஸ் இன்வாய்ஸ் போடப்படும்.",
  "kh.sale": "சரக்கு இப்போது போகும், டாக்ஸ் இன்வாய்ஸ் பிறகு வரும். உதாரணமாக டெலிவரியின்போது எடை போட்டு அளவு தெரியும்போது.",
  "kh.transfer": "உங்கள் சொந்த பிராஞ்ச் அல்லது குடோனுக்கு மாற்றும் சரக்கு.",
  "kh.other": "கண்காட்சி, ரிப்பேர், சரக்கு திருப்பி அனுப்புதல், சாம்பிள் அல்லது வேறு காரணம்.",
