  "k.debit": "டெபிட் நோட்",
  "kh.credit": "வாடிக்கையாளர் தர வேண்டிய தொகையைக் குறைக்கும்: சரக்கு திரும்பியது, விலை குறைப்பு அல்லது இன்வாய்ஸுக்குப் பிறகு தள்ளுபடி.",
  "kh.debit": "வாடிக்கையாளர் தர வேண்டிய தொகையைக் கூட்டும்: விலை குறைவாகப் போட்டது, அல்லது கூடுதல் சரக்கு அல்லது டாக்ஸ் வசூலிக்க வேண்டியது.",
