  "kh.pay": "ஒரு பில்லுக்காக அல்லது விற்பனைக்காக வந்த பணம்.",
  "kh.adv": "சப்ளை செய்வதற்கு முன் வந்த பணம். டாக்ஸ் இன்வாய்ஸ் பிறகு வரும் என்று ரசீதில் இருக்கும்.",
