  "gi.e.state": "“{s}” ஒரு GST மாநிலக் குறியீடு இல்லை.",
  "gi.st25": "டாமன் டையூ (பழைய குறியீடு)",
  "gi.w25": "குறியீடு 25 டாமன் டையூவுக்கானது; 26 ஜனவரி 2020 அன்று அது தாத்ரா நகர் ஹவேலியுடன் இணைந்தது, இப்போது அங்கு பதிவுகள் 26 உடன் வருகின்றன.",
  "gi.e.pan": "எழுத்து 3 முதல் 12 வரை PAN ஆக இருக்க வேண்டும்: 5 எழுத்து, 4 எண், 1 எழுத்து (ABCDE1234F போல).",
  "gi.e.tan": "14-வது எழுத்து D என்றால், எழுத்து 3 முதல் 12 வரை TAN ஆக இருக்க வேண்டும்: 4 எழுத்து, 5 எண், 1 எழுத்து.",
  "gi.w.holder": "PAN-ன் 4-வது எழுத்து (“{c}”) வழக்கமான ஹோல்டர் வகைகளில் இல்லை.",
  "gi.e.n13": "13-வது எழுத்து 0 ஆக இருக்க முடியாது; ஒரு மாநிலத்தில் ஒரு PAN-ன் முதல் பதிவு 1.",
  "gi.k.Z": "Z: சாதாரண டாக்ஸ்பேயர்",
  "gi.k.D": "D: டாக்ஸ் டிடக்டர் (GST-ல் TDS)",
  "gi.k.C": "C: டாக்ஸ் கலெக்டர் (TCS, இ-காமர்ஸ் ஆப்பரேட்டர்)",
  "gi.k.x": "சிறப்பு பதிவு",
  "gi.w14": "14-வது எழுத்து வழக்கமாக Z. “{c}” சிறப்பு பதிவுகளில் மட்டுமே வரும்; இந்த எண்ணை GST போர்ட்டலில் சரிபார்க்கவும்.",
  "gi.e.chk": "கடைசி எழுத்து {c} ஆக இருக்க வேண்டும், {x} அல்ல. ஏதோ ஒரு எழுத்து தவறாக டைப் ஆகியிருக்கலாம்.",
