  "app.nophone": "{p} இன் போன் எண் சேமிக்கப்படவில்லை. என் டேட்டாவில் சேர்க்கவும், அல்லது WhatsApp-இல் கான்டாக்டைத் தேர்ந்தெடுக்கவும்.",
