  "app.cbh": "உங்கள் விற்பனை, ரசீதுகள், பேமென்ட்கள், வாங்கிய பில்கள், செலவுகளின் ஒவ்வொரு கேஷ் மற்றும் பேங்க் என்ட்ரி.",
  "app.makeinv": "இன்வாய்ஸ்",
  "app.makeso": "சேல்ஸ் ஆர்டர்",
  "app.makedc": "டெலிவரி சலான்",
  "app.made": "உருவானது: {x}",
  "app.local": "டேட்டா ஹோம் திறக்கவில்லை, அதனால் இந்த தளத்தில் இந்த பிரவுசரில் மட்டும் சேமிக்கப்பட்டுள்ளது. அடுத்த முறை டேட்டா ஹோமுக்குச் செல்லும்.",
  "app.vault": "இந்த பிரவுசரின் டேட்டா ஹோமில் சேமிக்கப்பட்டுள்ளது, இது Nivesh Sahayak இன் எல்லா டூல்களுக்கும் பொதுவானது. எங்களுக்கு எதுவும் அனுப்பப்படுவதில்லை.",
  "app.help": "இது எப்படி வேலை செய்கிறது",
  "app.helpp": "billing., cash-memo., credit-note. இல் செய்த பில்கள் இங்கே தானாகத் தெரியும். வந்த, கொடுத்த பணத்தை இங்கே பதியுங்கள்; ஆப் அதை பில்களுடன் இணைக்கிறது, அட்வான்ஸை வைத்துக்கொள்கிறது, நிலுவையையும் கையிலுள்ள கேஷையும் கணக்கிடுகிறது.",
  "app.invfix": "இங்கே தீர்ந்த இன்வாய்ஸ்கள் பில்லிங் தளத்திலும் செலுத்தப்பட்டதாகக் காட்டும்.",
  "app.ex_rent": "வாடகை",
  "app.ex_power": "மின்சாரம்",
  "app.ex_salary": "சம்பளம் மற்றும் கூலி",
  "app.ex_transport": "போக்குவரத்து மற்றும் லாரி வாடகை",
