  "g1.filesh": "இவற்றை GST போர்ட்டலில் உள்ள இலவச Returns Offline Tool-இல் இம்போர்ட் செய்யவும். GSTR-1-இல் நீங்கள் அப்லோட் செய்யும் JSON ஃபைலை அது உருவாக்கும்.",
