  "g1.xfail": "Excel ஃபைலை உருவாக்க முடியவில்லை. இன்டர்நெட் இணைப்பைப் பார்த்து மீண்டும் முயலவும், அல்லது CSV ஃபைல்களைப் பயன்படுத்தவும்.",
