  "g1.s.cdnr": "பதிவு பெற்ற வாங்குபவர்களுக்கான கிரெடிட், டெபிட் நோட்டுகள்",
  "g1.s.cdnur": "பதிவு இல்லாத வாங்குபவர்களுக்கான கிரெடிட், டெபிட் நோட்டுகள் (B2C Large மற்றும் ஏற்றுமதிகள்)",
