  "nav.ewb": "இ-வே பில்",
  "f.ewbm": "இ-வே பில் JSON மேக்கர்",
  "bk.gstin": "வரிசை {r}: GSTIN {v} சரியாக இல்லை (டைப் தவறு இருக்கலாம், பாருங்கள்). ரெஜிஸ்டர் ஆகாத வாங்குபவர் என்றால் காலியாக விடுங்கள்.",
  "nav.exp": "ஏற்றுமதி இன்வாய்ஸ்",
  "f.expm": "ஏற்றுமதி மற்றும் SEZ இன்வாய்ஸ் மேக்கர்",
  "doc.exp": "ஏற்றுமதி இன்வாய்ஸ்",
  "docs.exp": "ஏற்றுமதி இன்வாய்ஸ்கள்",
  "Doc.exp": "ஏற்றுமதி இன்வாய்ஸ்",
  "k.expwp": "IGST செலுத்தி ஏற்றுமதி",
  "k.expwop": "LUT அல்லது பாண்டில் ஏற்றுமதி (IGST இல்லை)",
  "k.sezwp": "IGST செலுத்தி SEZ சப்ளை",
  "k.sezwop": "LUT அல்லது பாண்டில் SEZ சப்ளை (IGST இல்லை)",
  "kh.expwp": "சாதாரண விகிதத்தில் IGST; பொருட்களுக்கு அது ஷிப்பிங் பில் மூலம் திரும்பக் கிடைக்கும்.",
  "kh.expwop": "இந்த ஆண்டுக்கான Letter of Undertaking (Form GST RFD-11) தேவை. ஒவ்வொரு ஐட்டத்துக்கும் GST 0%.",
  "kh.sezwp": "SEZ உங்கள் சொந்த மாநிலத்தில் இருந்தாலும் IGST தான். SEZ யூனிட்டின் GSTIN-ஐ டைப் செய்யுங்கள்.",
  "kh.sezwop": "உங்கள் LUT-இன் கீழ்: ஒவ்வொரு ஐட்டத்துக்கும் GST 0%. SEZ யூனிட்டின் GSTIN-ஐ டைப் செய்யுங்கள்.",
  "lg.exp": "ஏற்றுமதி விவரங்கள்",
  "x.cur": "இன்வாய்ஸ் கரன்சி",
  "x.fx": "எக்ஸ்சேஞ்ச் ரேட் (1 யூனிட்டுக்கு ₹)",
  "x.h.fx": "இந்த இன்வாய்ஸுக்கு நீங்கள் பயன்படுத்தும் ரேட்டை டைப் செய்யுங்கள். மேலே உள்ள தொகைகள் ரூபாயிலேயே இருக்கும்.",
  "x.fcv": "இன்வாய்ஸ் மதிப்பு: {cur} {v}",
  "x.country": "சென்று சேரும் நாடு",
  "x.choose": "நாட்டைத் தேர்ந்தெடுங்கள்",
  "x.port": "போர்ட் கோடு",
  "x.h.port": "ஆறு எழுத்துகள், எடுத்துக்காட்டு INNSA1 (நவா ஷேவா). உங்கள் கஸ்டம்ஸ் புரோக்கரிடம் கேளுங்கள்.",
  "x.sbno": "ஷிப்பிங் பில் நம்பர்",
  "x.sbdate": "ஷிப்பிங் பில் தேதி",
  "x.h.sb": "இன்வாய்ஸுக்குப் பிறகுதான் தெரிவது வழக்கம்: அப்போது சேர்த்து மீண்டும் சேவ் செய்யுங்கள்.",
  "x.lut": "LUT ரெஃபரென்ஸ் (ARN)",
  "x.lutdate": "LUT தேதி",
  "x.h.lut": "இந்த நிதியாண்டுக்கு GST போர்ட்டலில் நீங்கள் தாக்கல் செய்த Letter of Undertaking-இல் இருந்து.",
  "x.refund": "இந்த சப்ளைக்கு ரீஃபண்ட் கோருகிறேன் (இ-இன்வாய்ஸ் ஃபைலுக்கு)",
  "v.lut0": "LUT அல்லது பாண்டில் (IGST இல்லை) ஒவ்வொரு ஐட்டத்துக்கும் GST 0% இருக்க வேண்டும்.",
