  "bc.codesh": "பார்கோடில் இருப்பது இந்த கோடுதான். கம்பெனி பேக்கில் அச்சிட்ட எண்ணை (EAN-13) போடுங்கள், அல்லது உங்கள் சொந்த கோடு. ஒவ்வொரு ஐட்டத்துக்கும் தனி கோடு வேண்டும்.",
  "bc.ean_ok": "சரியான EAN-13",
  "bc.ean_bad": "EAN-13 செக் டிஜிட் தவறு",
  "bc.dup": "கோடு {c} இரண்டு ஐட்டங்களுக்கு உள்ளது. ஒவ்வொரு ஐட்டத்துக்கும் சொந்த கோடு வேண்டும்.",
  "bc.scan": "பார்கோடு ஸ்கேன் செய்யுங்கள்",
  "bc.scanh": "போன் கேமராவை பார்கோடு நோக்கிக் காட்டுங்கள், அல்லது USB பார்கோடு ஸ்கேனர் பயன்படுத்துங்கள்: கீழே உள்ள பெட்டியில் கிளிக் செய்து ஸ்கேன் செய்யுங்கள். ஒவ்வொரு ஸ்கேனுக்கும் 1 கூடும். தெரியாத கோடை புதிய ஐட்டமாக சேவ் செய்யலாம்.",
