  "bc.got": "ஸ்கேன் ஆனது {c}",
  "bc.nocam": "இந்த பிரவுசரால் கேமராவைத் திறக்க முடியாது. USB ஸ்கேனர் பயன்படுத்துங்கள் அல்லது கோடை டைப் செய்யுங்கள்.",
  "bc.camfail": "கேமரா தொடங்கவில்லை. இந்த சைட்டுக்கு கேமரா அனுமதி கொடுங்கள், அல்லது USB ஸ்கேனர் பயன்படுத்துங்கள்.",
