  "br.starth": "சரிபார்க்க வேண்டிய மாதத்தின் ஸ்டேட்மென்டை நெட் பேங்கிங்கிலிருந்து Excel அல்லது CSV-ஆக டவுன்லோட் செய்து இங்கே திறங்கள். ஃபைல் இந்த பிரவுசரிலேயே படிக்கப்படும்; எதுவும் அப்லோட் ஆகாது.",
  "br.s1": "ஸ்டேட்மென்ட் ஃபைலைத் திறங்கள், அல்லது பேங்க் வரிகளைக் கையால் டைப் செய்யுங்கள்.",
  "br.s2": "ஒரே தொகை உள்ள வரிகள் உங்கள் சேவ் செய்த ரசீது, பேமென்ட், செலவு, கேஷ் டெபாசிட்டுடன் பொருத்தப்படும்.",
  "br.s3": "இரு பக்கமும் என்ன மீதி என்று பார்த்து, விடுபட்ட என்ட்ரிகளைச் சேர்த்து, ரீகன்சிலியேஷனை சேவ் அல்லது பிரிண்ட் செய்யுங்கள்.",
  "br.nolines": "இந்த ஃபைலில் பேங்க் வரி எதுவும் கிடைக்கவில்லை. கீழே எந்த காலம் எது என்று சொல்லுங்கள்.",
