  "pl.cs": "{d} அன்று குளோசிங் ஸ்டாக்",
  "pl.stockh": "விற்பனை, வாங்குதல், செலவுகள், பணம், நிலுவை உங்கள் சேமித்த பதிவுகளில் இருந்து வரும்; ஸ்டாக் மதிப்பு ஸ்டாக் ரெஜிஸ்டரில் இருந்து. ரெஜிஸ்டர் மதிப்பைப் பயன்படுத்த ஸ்டாக் பெட்டிகளைக் காலியாக விடுங்கள், அல்லது ஸ்டாக் எண்ணிக்கையின் மதிப்பை டைப் செய்யுங்கள். ஃபிக்ஸட் அசெட், தேய்மானம் (டெப்ரிசியேஷன்), கேபிடல், லோன், டிராயிங்ஸ் ஆகியவற்றை டைப் செய்த வரியாகச் சேர்க்கவும்.",
  "pl.typedh": "டிரையல் பேலன்ஸின் ஒவ்வொரு பேலன்ஸையும் ஒரு வரியில் டைப் செய்யுங்கள் (உதாரணமாக Tally அல்லது லெட்ஜரில் இருந்து), மேலே ஓப்பனிங், குளோசிங் ஸ்டாக்.",
  "pl.k_rev": "விற்பனை (ரெவின்யூ)",
  "pl.k_gross": "கிராஸ் லாபம்",
  "pl.k_profit": "நிகர லாபம்",
  "pl.k_loss": "நிகர நஷ்டம்",
  "pl.k_tb": "டிரையல் பேலன்ஸ் வித்தியாசம்",
  "pl.agrees": "சரியாக உள்ளது",
  "pl.w_diff": "டிரையல் பேலன்ஸ் சரியாக இல்லை: {s} பக்கம் {x} அதிகம். டைப் செய்த ஒரு வரிக்கு ஒரே பக்கம் உள்ளது, அல்லது ஒரு ஓப்பனிங் பேலன்ஸ் விடுபட்டுள்ளது.",
  "pl.dr": "டெபிட்",
  "pl.cr": "கிரெடிட்",
  "pl.w_neg": "{a} பூஜ்ஜியத்துக்குக் கீழே உள்ளது. ஓப்பனிங் பேலன்ஸை டைப் செய்த வரியாகச் சேர்க்கவும்: டெபிட் பக்கத்தில் {a}, கிரெடிட் பக்கத்தில் கேபிடல்.",
  "pl.w_nosales": "இந்தக் காலத்தில் விற்பனை எதுவும் கிடைக்கவில்லை. தேதிகள், தேர்ந்தெடுத்த வணிகத்தைச் சரிபாருங்கள், அல்லது கணக்கை டைப் செய்யுங்கள்.",
