  "pl.bsdiff": "வித்தியாசம்",
  "pl.bsh": "இந்தக் காலத்தின் லாபம் ரிசர்வ் மற்றும் சர்ப்ளஸில் சேரும். உரிமையாளர் அல்லது பார்ட்னருக்கு இது பொதுவாக கேபிடல் கணக்கில் காட்டப்படும்.",
  "pl.tbas": "{d} அன்று டிரையல் பேலன்ஸ்",
  "pl.tbh": "ஒவ்வொரு கணக்கும் அதன் ஹெடுடன். லாப நஷ்டக் கணக்குகள் காலத்துக்குள் நடந்தவை; பேலன்ஸ் ஷீட் கணக்குகள் கடைசி நாளின் பேலன்ஸ். ஒரு வரி வேறு ஹெடுக்குச் சேர்ந்தது என்றால் அதன் ஹெடை மாற்றவும்.",
  "pl.acct": "கணக்கு",
  "pl.head": "ஹெட்",
  "pl.typed": "டைப் செய்தது",
  "pl.csnote": "குளோசிங் ஸ்டாக் {x} டிரையல் பேலன்ஸில் இல்லை: இது இன்வென்டரியாகக் காட்டப்பட்டு பொருள் விலையில் இருந்து கழிக்கப்படும்.",
  "pl.lineh": "டைப் செய்த வரி என்பது டிரையல் பேலன்ஸின் ஒரு கணக்கு, அதன் ஹெடுடன். பெரும்பாலான சரிசெய்தல்களுக்கு ஒன்றையொன்று சமன் செய்யும் இரண்டு வரிகள் தேவை, உதாரணமாக தேய்மானம் (டெபிட்), அதே தொகை ஃபர்னிச்சரில் இருந்து குறைப்பு (கிரெடிட்).",
  "pl.drcrh": "டெபிட்: சொத்துகள், செலவுகள், டிராயிங்ஸ். கிரெடிட்: கேபிடல், லோன், கொடுக்க வேண்டியவை, வருமானம்.",
