  "hs.n.b2c": "₹5 கோடி வரை டர்ன்ஓவர் என்றால் பதிவு இல்லாத வாங்குபவர் பில்லில் HSN இலக்கங்களை விடலாம் (Notification 78/2020-Central Tax).",
  "hs.n.b2cbig": "₹5 கோடிக்கு மேல் டர்ன்ஓவர் என்றால் ஒவ்வொரு இன்வாய்ஸிலும், B2C-யிலும், குறைந்தது 6 இலக்கங்கள் தேவை.",
