  "hs.rate": "GST விகிதம் முழு கோட் மற்றும் அதிகாரப்பூர்வ விகித அறிவிப்பின் விவரத்தைப் பொறுத்தது; இவை 22 செப்டம்பர் 2025 மற்றும் மீண்டும் 2026-இல் மாறின. சரியான விகிதத்தைக் கீழே உள்ள அதிகாரப்பூர்வ தேடலில் பாருங்கள்.",
