  "hs.f.lbl": "கோட் அல்லது சொல்லால் தேடுங்கள்",
  "hs.f.none": "எதுவும் கிடைக்கவில்லை. வேறு சொல்லை முயலுங்கள், அல்லது GST போர்ட்டலில் தேடுங்கள்.",
  "hs.f.next": "முடிவைத் தட்டிச் சரிபார்க்கவும், பிறகு முழு 6 அல்லது 8 இலக்கங்களை GST போர்ட்டலில் பாருங்கள்.",
  "hs.h.items": "சேவ் செய்த பொருட்களின் HSN மற்றும் GST %",
  "hs.i.help": "Nivesh Sahayak-இல் சேவ் செய்த ஒவ்வொரு பொருளும் சர்வீஸும், உங்கள் டர்ன்ஓவர்படி சரிபார்க்கப்படும். இங்கே கோடைத் திருத்தி சேவ் அழுத்தவும்.",
  "hs.i.none": "இன்னும் சேவ் செய்த பொருட்கள் இல்லை. எந்த Nivesh Sahayak டாக்குமெண்ட் மேக்கரிலும் சேர்த்த பொருட்கள் இங்கே தெரியும்.",
  "hs.i.sum": "சேவ் செய்த பொருட்கள்: {n}. பார்க்க வேண்டியவை: {bad}.",
