  "hs.r.many": "ஒன்றுக்கு மேற்பட்ட விகிதங்கள். உங்கள் பொருளுக்குப் பொருந்தும் விவரம் உள்ள என்ட்ரியைத் தேர்ந்தெடுக்கவும்.",
