  "b1.rep_stopped": "நிறுத்தப்பட்டது",
  "b1.rep_waiting": "{n} மீண்டும் வரும் பில்கள் போட வேண்டியுள்ளன.",
  "b1.rep_see": "பார்த்து போடு",
  "b1.bin": "ரீசைக்கிள் பின்",
  "b1.binp": "நீக்கிய பிசினஸ், பார்ட்டி, ஐட்டம், டாக்குமென்ட் இங்கே {n} நாள் இருக்கும், பிறகு நிரந்தரமாகப் போய்விடும். ரீஸ்டோர் செய்தால் முன்பு போலவே திரும்ப வரும்.",
  "b1.binnone": "ரீசைக்கிள் பின் காலியாக உள்ளது.",
  "b1.binempty": "பின்னை இப்போதே காலி செய்",
  "b1.binemptyc": "ரீசைக்கிள் பின்னில் உள்ள அனைத்தையும் நிரந்தரமாக நீக்கவா?",
  "b1.restore": "ரீஸ்டோர்",
  "b1.restored": "ரீஸ்டோர் ஆனது.",
  "b1.delon": "{d} அன்று நீக்கப்பட்டது",
  "b1.daysleft": "{n} நாள் மீதம்",
  "b1.cdel": "{x} ஐ நீக்கவா? இது 30 நாள் ரீசைக்கிள் பின்னில் இருக்கும், அங்கிருந்து ரீஸ்டோர் செய்யலாம்.",
  "b1.binned": "ரீசைக்கிள் பின்னுக்குப் போனது. 30 நாள் வரை ரீஸ்டோர் செய்யலாம்.",
  "b1.hist": "மாற்றப் பதிவு",
  "b1.changes": "மாற்றங்கள்",
  "b1.changesof": "மாற்றங்கள்: {no}",
  "b1.nolog": "இன்னும் எந்த மாற்றமும் பதிவாகவில்லை.",
  "b1.thisdev": "இந்த சாதனம்",
  "b1.logp": "எந்த Nivesh Sahayak சைட்டிலும் பிசினஸ், பார்ட்டி, ஐட்டம் அல்லது டாக்குமென்ட் சேர்க்கப்பட்டால், மாற்றப்பட்டால், நீக்கப்பட்டால் அல்லது ரீஸ்டோர் செய்யப்பட்டால் தேதி, நேரம், பெயர், என்ன மாறியது என்று இங்கே பதிவாகும். இந்தப் பதிவுகளை மாற்றவோ நீக்கவோ முடியாது.",
  "b1.logrule": "1 ஏப்ரல் 2023 முதல் கம்பெனிகள் இப்படி ஆடிட் ட்ரெயில் வைக்கும் அக்கவுண்ட்ஸ் சாஃப்ட்வேரைப் பயன்படுத்த வேண்டும் (கம்பெனிகள் (அக்கவுண்ட்ஸ்) விதிகள் 2014, விதி 3(1)). இது இந்த பிரவுசரிலும் உங்கள் பேக்கப் ஃபைலிலும் இருக்கும்.",
  "b1.logmore": "{n} இல் புதிய 300 காட்டப்படுகின்றன. அனைத்துக்கும் Excel ஃபைலை டவுன்லோட் செய்யுங்கள்.",
  "b1.itemn": "ஐட்டம் {n}",
  "b1.chargen": "சார்ஜ் {n}",
