  "b1.a_restore": "ரீஸ்டோர் ஆனது",
  "b1.a_import": "பேக்கப் திரும்பக் கொண்டுவரப்பட்டது",
  "b1.g_safe": "பாதுகாப்பு",
  "b1.who": "இந்த சாதனத்தில் உங்கள் பெயர்",
  "b1.h_who": "இந்த சாதனத்தில் செய்யும் ஒவ்வொரு மாற்றத்துடனும் மாற்றப் பதிவில் தெரியும்.",
  "b1.lock": "இந்தத் தேதிக்கு முந்தைய டாக்குமென்ட்களை லாக் செய்",
  "b1.h_lock": "இந்த நாளுக்கு முந்தைய தேதியுள்ள டாக்குமென்ட்களை எந்த சைட்டிலும் சேர்க்கவோ, மாற்றவோ, நீக்கவோ முடியாது (பணம் வந்தது என்று குறிப்பது செயல்படும்). GST ரிட்டர்ன் தாக்கல் அல்லது கணக்கு முடித்த பின் பயன்படுத்துங்கள்.",
  "b1.lockc": "{d} க்கு முந்தைய தேதியுள்ள எல்லா டாக்குமென்ட்களையும் லாக் செய்யவா? இந்தத் தேதியை நீக்கும் வரை மாற்ற முடியாது.",
  "b1.unlockc": "பழைய டாக்குமென்ட்களை மீண்டும் மாற்ற அன்லாக் செய்யவா?",
  "b1.locked": "லாக் உள்ளது: {d} க்கு முந்தைய தேதியுள்ள டாக்குமென்ட்களை மாற்ற முடியாது. முதலில் செட்டிங்ஸ் மற்றும் சேவ் டேட்டா › செட்டிங்ஸில் லாக் தேதியை நீக்குங்கள்.",
  "b1.pin_t": "PIN லாக்",
  "b1.pin_on": "ஆன்",
  "b1.pin_off": "ஆஃப்",
  "b1.pin_p": "PIN வைத்தால் உங்கள் டேட்டா இந்தத் திரையிலும் Nivesh Sahayak ஆப்பிலும் PIN போடும் வரை மறைந்திருக்கும். இது திரை லாக், என்க்ரிப்ஷன் அல்ல: டேட்டா மாறாது, டாக்குமென்ட் சைட்கள் பில் நிரப்ப அதைப் படிக்கலாம். PIN மறந்தால் திரும்ப வர ஒரே வழி: இந்த பிரவுசரின் டேட்டாவை அழித்து பேக்கப் ஃபைலை ரீஸ்டோர் செய்யுங்கள்.",
  "b1.pin_cur": "இப்போதைய PIN",
