  "b1.pin_why": "இந்த சாதனத்தில் Nivesh Sahayak லாக் ஆகியுள்ளது.",
  "b1.pin": "PIN",
  "b1.unlock": "திற",
  "b1.pin_wait": "பல முறை முயற்சி. {n} வினாடி காத்திருங்கள்.",
  "b1.forgot": "PIN மறந்துவிட்டதா?",
  "b1.forgotp": "PIN ஐ காட்டவோ ரீசெட் செய்யவோ முடியாது. உள்ளே வர இந்த பிரவுசரின் டேட்டாவை அழித்து உங்கள் கடைசி பேக்கப் ஃபைலை ரீஸ்டோர் செய்யுங்கள். அந்த பேக்கப்புக்குப் பின் சேவ் ஆனவை போய்விடும்.",
  "b1.erase": "இந்த பிரவுசரின் டேட்டாவை அழி",
  "b1.erase_c1": "இந்த பிரவுசரில் சேவ் ஆன ஒவ்வொரு பிசினஸ், பார்ட்டி, ஐட்டம், டாக்குமென்டையும் அழிக்கவா? உங்கள் பேக்கப் ஃபைல் மட்டுமே அவற்றைத் திரும்பக் கொண்டுவர முடியும்.",
  "b1.erased": "அழிக்கப்பட்டது. இப்போது உங்கள் பேக்கப் ஃபைலைத் தேர்ந்தெடுங்கள்.",
  "b1.wiz": "ஒரு நிமிடத்தில் தொடங்குங்கள்",
  "b1.wizp": "உங்கள் பிசினஸ் விவரம் ஒவ்வொரு பில்லிலும் அச்சாகும். பின்னர் மாற்றலாம், மேலும் பிசினஸ் சேர்க்கலாம்.",
  "b1.wiz_gst": "GST பதிவு இல்லையென்றால் காலியாக விடுங்கள்.",
  "b1.wiz_go": "சேவ் செய்து தொடங்கு",
  "b1.wiz_done": "உங்கள் பிசினஸ் சேவ் ஆனது. இப்போது வாடிக்கையாளர்களையும் ஐட்டங்களையும் சேர்க்கவும், அல்லது முதல் பில்லைப் போடவும்.",
  "b1.samp_try": "முதலில் மாதிரி டேட்டாவுடன் பாருங்கள்",
  "b1.samp_h": "மாதிரி டேட்டா என்பது \"Sharma Hardware (sample)\" என்ற கற்பனை பிசினஸ், வாடிக்கையாளர்கள், ஐட்டங்கள், பில்கள், ஒரு பேமென்ட், ஒரு வாங்கல், எல்லாவற்றிலும் மாதிரி என்று குறிக்கப்பட்டது. ஒரே டேப்பில் எல்லாம் நீங்கும்.",
  "b1.samp_on": "மாதிரி டேட்டா ஆன்: மாதிரி என்று குறித்த பதிவுகள் கற்பனை.",
  "b1.samp_rm": "எல்லா மாதிரி பதிவுகளையும் நீக்கு",
