  "b1.samp_gone": "{n} மாதிரி பதிவுகள் நீக்கப்பட்டன.",
  "b1.samp_added": "மாதிரி டேட்டா சேர்க்கப்பட்டது. பார்த்துவிட்டு, ஒரே டேப்பில் நீக்குங்கள்.",
  "b1.sample": "மாதிரி",
