  "b1.rp_dues": "நிலுவை",
  "b1.rp_duesp": "இன்று யாரிடம் வர வேண்டும், யாருக்குக் கொடுக்க வேண்டும், எவ்வளவு பழையது, கிரெடிட் லிமிட், டியூ டேட் தாண்டிய தொகையுடன்.",
