  "b2.nojv": "இன்னும் ஜர்னல் என்ட்ரி இல்லை.",
  "b2.jvh": "எந்த பில்லோ பேமெண்டோ பொருந்தாதபோது, ஜர்னல் என்ட்ரி தொகையை ஒரு கணக்கிலிருந்து இன்னொரு கணக்குக்கு மாற்றுகிறது: கொடுத்த அல்லது கிடைத்த தள்ளுபடி, போட்ட வட்டி, வராக்கடன் (பேட் டெப்ட்), கொண்டுவந்த முதலீடு, சொந்த எடுப்பு, கடன், அல்லது ஒரு திருத்தம். டெபிட்டும் கிரெடிட்டும் சமமாக இருக்க வேண்டும்.",
  "b2.jvhelp": "ஒவ்வொரு வரியிலும் ஒரு கணக்கும் டெபிட் (Dr) அல்லது கிரெடிட் (Cr) தொகையும் இருக்கும். பார்ட்டி வரி வாடிக்கையாளர் தர வேண்டியதை அல்லது சப்ளையருக்கு நீங்கள் தர வேண்டியதை மாற்றும்; அது அவர்களின் ஸ்டேட்மெண்ட் மற்றும் நிலுவையில் தெரியும். செலவும் மற்ற வருமானமும் லாப நஷ்டக் கணக்கில் போகும்; முதலீடு, எடுப்பு, கடன் மற்றும் ஃபிக்ஸ்டு அசெட் பேலன்ஸ் ஷீட்டில்.",
