  "b2.fah": "உங்கள் வியாபாரம் பல ஆண்டுகள் பயன்படுத்தும் மெஷின்கள், கம்ப்யூட்டர்கள், ஃபர்னிச்சர், வாகனங்கள் மற்றும் கட்டடங்கள். பதிவேடு ஒவ்வொரு ஆண்டின் தேய்மானத்தைக் கணக்கிடும்; ஒரு டேப்பில் அதைக் கணக்கில் போடலாம்.",
  "b2.todo": "FY {fy} க்கான {a} தேய்மானம் இன்னும் உங்கள் கணக்கில் இல்லை.",
