  "b2.salegst": "விற்பனையில் GST",
  "b2.salegsth": "வியாபாரத்தின் பழைய அசெட்டை விற்பதும் சப்ளைதான்; எந்த விற்பனையையும் போல GST உண்டு. எந்த மதிப்பை எடுப்பது என்று உங்கள் அக்கவுண்டண்டிடம் கேளுங்கள்.",
  "b2.recdby": "பணம் எப்படி வந்தது",
  "b2.buyer": "வாங்குபவர்",
  "b2.bvon": "{d} அன்று புக் மதிப்பு: {a}. வித்தியாசம் விற்பனையில் லாபம் அல்லது நஷ்டம்.",
