  "b2.costh": "விலை, வண்டிக் கூலி மற்றும் இன்ஸ்டலேஷன், நீங்கள் திரும்ப கிளெய்ம் செய்யும் GST தவிர.",
  "b2.gstamt": "பில்லில் GST",
  "b2.itc": "GST இன்புட் டேக்ஸ் கிரெடிட்டில் எடுத்தது",
