  "b2.slm": "ஸ்ட்ரெயிட் லைன் (SLM)",
  "b2.life": "பயன்பாட்டு ஆயுள் (ஆண்டுகள்)",
  "b2.lifeh": "இந்த வகை அசெட்டின் ஷெட்யூல் II ஆயுள்; அக்கவுண்டண்ட் சொன்னால் மாற்றவும்.",
  "b2.resid": "மீதி மதிப்பு (விலையின் %)",
  "b2.residh": "பொதுவாக 5% க்கு மேல் இல்லை.",
  "b2.itrate": "வருமான வரி பிளாக் ரேட் (%)",
  "b2.itrateh": "கீழே உள்ள வருமான வரி கணக்குக்கு மட்டும்.",
  "b2.fadup": "{n} என்ற பெயரில் ஒரு அசெட் ஏற்கனவே சேமிக்கப்பட்டுள்ளது. இதற்கு வேறு பெயர் கொடுங்கள் (எ.கா. ஒரு எண் சேர்க்கவும்).",
  "b2.fasold": "இந்த அசெட்டின் விற்பனை சேமிக்கப்பட்டுள்ளது. முதலில் அதை நீக்கவும்.",
  "b2.itblock": "வருமான வரி தேய்மானம், FY {fy}",
  "b2.itblockh": "அசெட் பிளாக் வாரியாக, வருமான வரி ரிட்டர்னுக்கு மட்டும் (கணக்கில் போடப்படாது).",
  "b2.rate": "ரேட்",
  "b2.openwdv": "தொடக்க WDV",
  "b2.addfull": "சேர்த்தது (180 நாள் அல்லது அதிகம்)",
  "b2.addhalf": "சேர்த்தது (180 நாளுக்குக் குறைவு)",
  "b2.sales": "விற்ற தொகை",
  "b2.dep": "தேய்மானம்",
  "b2.closewdv": "இறுதி WDV",
  "b2.gain": "லாபம் {a}: அக்கவுண்டண்டிடம் கேளுங்கள்",
  "b2.farules": "தேய்மானம் எப்படிக் கணக்கிடப்படுகிறது",
  "b2.farule1": "கணக்கு தேய்மானம் கம்பெனிகள் சட்டம், 2013 ஷெட்யூல் II படி: ஒவ்வொரு வகை அசெட்டுக்கும் பயன்பாட்டு ஆயுள் உண்டு (எ.கா. கம்ப்யூட்டர் 3 ஆண்டு, ஃபர்னிச்சர் 10 ஆண்டு, பிளான்ட் மற்றும் மெஷினரி 15 ஆண்டு, கார் 8 ஆண்டு), மீதி மதிப்பு பொதுவாக விலையின் 5% க்கு மேல் இருக்காது, ஆண்டின் நடுவில் சேர்த்த அல்லது விற்ற அசெட்டுக்கு பயன்படுத்திய நாட்களுக்கு மட்டுமே தேய்மானம். ஸ்ட்ரெயிட் லைன் (SLM: ஒவ்வொரு ஆண்டும் அதே தொகை) அல்லது ரிட்டன் டவுன் வேல்யூ (WDV: மீதித் தொகையில் நிலையான ரேட்) தேர்வு செய்யுங்கள். புரொப்ரைட்டர்களும் ஃபர்ம்களும் பெரும்பாலும் இதே முறையைப் பின்பற்றுகின்றனர்; முடிவு உங்கள் அக்கவுண்டண்டுடையது.",
  "b2.farule2": "வருமான வரி தேய்மானம் ஒவ்வொரு பிளாக்குக்கும் தனியாகக் கணக்கிடப்படும்: பிளாக் ரேட்டில் ரிட்டன் டவுன் வேல்யூ (எ.கா. பிளான்ட் மற்றும் மெஷினரி 15%, ஃபர்னிச்சர் 10%, கம்ப்யூட்டர் 40%), ஆண்டில் 180 நாளுக்குக் குறைவாகப் பயன்பட்ட அசெட்டுக்கு பாதி ரேட், விற்ற பணம் பிளாக்கிலிருந்து கழியும். இது வருமான வரி ரிட்டர்னுக்கு மட்டும், கணக்கில் ஒருபோதும் போடப்படாது. நிரப்பிய ரேட்கள் வழக்கமான பிளாக் ரேட்கள்: உங்கள் அக்கவுண்டண்டிடம் உறுதி செய்யுங்கள், குறிப்பாக 1 ஏப்ரல் 2026 முதல் வருமான வரிச் சட்டம், 2025 கீழ் வரும் ஆண்டுகளுக்கு.",
  "b2.farule3": "நீங்கள் 'தேய்மானத்தைப் போடு' அழுத்தினால் மட்டுமே தேய்மானம் கணக்கில் செல்லும்: ஆண்டின் கடைசி நாள் (அல்லது ஆண்டின் நடுவில் இன்று) தேதியிட்ட ஜர்னல் என்ட்ரி தேய்மானத்தை டெபிட் செய்து ஒவ்வொரு அசெட்டையும் குறைக்கும். பிறகு அசெட்டை மாற்றினால் மீண்டும் போடுங்கள், வித்தியாசம் மட்டும் சேரும்.",
  "b2.k_bldg_off": "கட்டடம்: அலுவலகம் அல்லது கடை",
  "b2.k_bldg_fac": "கட்டடம்: தொழிற்சாலை",
  "b2.k_bldg_res": "கட்டடம்: குடியிருப்பு",
