  "b2.ck_open": "{n} கொட்டேஷன், புரொஃபார்மா இன்வாய்ஸ் அல்லது சேல்ஸ் ஆர்டர் இன்னும் திறந்திருக்கின்றன.",
  "b2.nextyear": "FY {fy} க்கு",
  "b2.carryh": "இந்த டேட்டா ஹோமில் எதையும் நகர்த்த வேண்டாம்: பார்ட்டி இருப்பு, கேஷ், பேங்க் மற்றும் ஸ்டாக் தானாகவே புதிய ஆண்டுக்குத் தொடரும், ஏனெனில் ஆப் ஒவ்வொரு சேமித்த பதிவிலிருந்தும் கணக்கிடுகிறது.",
  "b2.numh": "ஒவ்வொரு நிதியாண்டிலும் ஆவண எண்கள் மீண்டும் 001 இல் தொடங்கும் (எ.கா. INV/27-28/001), அதே முன்னொட்டுடன், எனவே புதிய ஆண்டுக்கு எதையும் மாற்ற வேண்டியதில்லை.",
  "b2.closet": "ஆண்டை மூடு",
  "b2.closeh": "ஆண்டை மூடினால் அது படிக்க மட்டுமே: ஆப்பும் ஒவ்வொரு டாக்குமெண்ட் மேக்கரும் அதற்குள் தேதியிட்ட எதையும் சேமிக்க, மாற்ற அல்லது நீக்க விடாது. எப்போது வேண்டுமானாலும் இங்கே மீண்டும் திறக்கலாம்.",
  "b2.reopenh": "இந்த ஆண்டு மூடப்பட்டுள்ளது: அதற்குள் தேதியிட்ட எதையும் சேமிக்க, மாற்ற அல்லது நீக்க முடியாது.",
  "b2.close": "FY {fy} மூடு",
