  "b2.newfile": "புதிய ஆண்டைப் புதிய டேட்டா ஃபைலில் தொடங்கு",
  "b2.newfileh": "புதிய பிரவுசருக்குப் போகிறீர்களா அல்லது புதிதாகத் தொடங்குகிறீர்களா? இந்த ஃபைலில் உங்கள் வியாபாரம், வாடிக்கையாளர்கள், சப்ளையர்கள், பொருட்கள், மற்றும் 1 ஏப்ரல் தொடக்க இருப்புகள்: ஒவ்வொரு பார்ட்டியின் இருப்பு, கேஷ், பேங்க், சராசரி விலையில் ஸ்டாக், ஃபிக்ஸ்டு அசெட், கடன், GST, TDS மற்றும் முதலீட்டுக்கு ஒரு ஜர்னல் என்ட்ரி (ஆண்டின் லாபம் முதலீட்டில் உள்ளது). அங்கே My data, பேக்கப்பில் ரீஸ்டோர் செய்யுங்கள்.",
  "b2.cfdl": "FY {fy} தொடக்க ஃபைலை டவுன்லோட் செய்",
  "b2.cfdone": "{n} தொடக்கப் பதிவுகளுடன் ஃபைல் சேமிக்கப்பட்டது.",
  "b2.gd": "குடோன் மற்றும் ஸ்டாக் டிரான்ஸ்ஃபர்",
  "b2.gdh": "ஒவ்வொரு குடோனின் ஸ்டாக்கும் பில்களில் தேர்ந்தெடுத்த குடோன் (மேலும் விவரங்கள்) மற்றும் டிரான்ஸ்ஃபர்களிலிருந்து வருகிறது. குடோன் இல்லாத பில்கள் மெயின் குடோனாகக் கொள்ளப்படும். டிரான்ஸ்ஃபரால் வியாபாரத்தின் மொத்த ஸ்டாக் மாறாது.",
