  "b2.profit": "லாப ரிப்போர்ட்",
  "b2.profith": "லாபம் = GST இல்லாத விற்பனைத் தொகை கழித்தல் பொருளின் விலை: பில் தேதி வரையிலான சராசரி கொள்முதல் விலை (தொடக்க ஸ்டாக், கொள்முதல் பில்கள், புரொடக்ஷன்). ஒருபோதும் வாங்காத பொருளுக்கு My data வில் சேமித்த கொள்முதல் விலை எடுக்கப்படும், இருந்தால். சர்வீஸுக்கு விலை கணக்கிடப்படாது.",
