  "b2.nosmrows": "இந்தத் தேதிகளில் விற்பனை இல்லை.",
  "b2.nosm1": "சேல்ஸ்மேன் இல்லாமல்",
  "b2.smanh": "ஒவ்வொரு பில்லிலும் சேல்ஸ்மேனைத் தேர்ந்தெடுங்கள் (மேலும் விவரங்கள்). நிகர விற்பனை = பில்கள் கழித்தல் கிரெடிட் நோட் (கிரெடிட் நோட் அது குறிப்பிடும் பில்லின் சேல்ஸ்மேனுக்குக் கணக்கிடப்படும்). வசூல் = அந்த பில்களில் ஏற்கனவே வந்த பணம். கமிஷன் நிகர விற்பனை அல்லது வசூலின் மேல், My data, செட்டிங்ஸில் வைத்தபடி.",
  "b2.hasbom": "பில் ஆஃப் மெட்டீரியல் (ஆப்பின் புரொடக்ஷனில் மாற்றவும்): {l}",
